#!/usr/bin/env python3
# Turns the text printed by Program.cs into tests/csharp_vectors.hpp.
# Usage: make_header.py out.txt > tests/csharp_vectors.hpp
import re, sys

H = """// Copyright (C) 2026 Thomas Fanning
// SPDX-License-Identifier: AGPL-3.0-or-later

#pragma once

// Vectors from the C# reference, M0LTE.Ms110d 0.2.0 (the NuGet package pinned in
// reference/pin.txt). Generated by tools/csharp-vectors (Program.cs prints them,
// make_header.py formats them); it calls only public types:
//   Ms110dScrambler.NextPsk / NextQam, Trinomial159Scrambler.Next, Ms110dInterleaver and
//   Ms110dInterleaverParams.Get3k / Has3k (the sizes and
//   increments themselves are in tests/data/csharp-tables-0.2.0.txt, see TablesDump.cs).
// Hashes are 64-bit FNV-1a over each value as a 32-bit little-endian word. Scrambler lists
// are the first outputs from a fresh register with input symbol 0 ("head"), and the hash of
// 1024 outputs (4200 for the trinomial); "mix" feeds the input symbol i % 8 (PSK) or
// i & (2^bits - 1) (QAM) instead. Interleaver rows come from the C# parameter table and give
// the first 16 load locations (the wire position of bit n, extracted by interleaving the
// indices 0..size-1 and inverting) and the hash of all of them, plus the hash of the
// fetched array when input byte i is (i & 255).
// Do not edit by hand; regenerate from the C# if the pin moves.

#include <cstdint>

namespace csharp_vectors {
"""
o = [H]
L = open(sys.argv[1]).read().splitlines()
lst = lambda s: "{" + s + "}"
for l in L:
    if l.startswith("psk0"):
        m = re.search(r"head32 \{(.*?)\} fnv (0x\w+)", l)
        o.append(f"inline constexpr int psk_head[32] = {lst(m[1])};\ninline constexpr std::uint64_t psk_fnv = {m[2]}ULL;")
    elif l.startswith("pskmix"):
        o.append(f"inline constexpr std::uint64_t psk_mix_fnv = {l.split()[-1]}ULL;")
    elif l.startswith("qam"):
        m = re.match(r"qam(\d) head32 \{(.*?)\} fnv (0x\w+) mixfnv (0x\w+)", l)
        b = m[1]
        o.append(f"inline constexpr int qam{b}_head[32] = {lst(m[2])};\ninline constexpr std::uint64_t qam{b}_fnv = {m[3]}ULL;\ninline constexpr std::uint64_t qam{b}_mix_fnv = {m[4]}ULL;")
    elif l.startswith("tri"):
        m = re.search(r"head64 \{(.*?)\} fnv4200 (0x\w+) fnv2048 (0x\w+) sym2048..2079 \{(.*?)\}", l)
        o.append(f"inline constexpr int tri_head[64] = {lst(m[1])};\ninline constexpr std::uint64_t tri_fnv4200 = {m[2]}ULL;\ninline constexpr std::uint64_t tri_fnv2048 = {m[3]}ULL;\ninline constexpr int tri_after_wrap[32] = {lst(m[4])};")
o.append("""
struct InterleaverVector {
    int wn;
    int kind;  // InterleaverKind order: 0 ultra-short, 1 short, 2 medium, 3 long
    // Size and increment are not repeated here: the test takes them from interleaver_3k(wn, kind).
    std::uint32_t load16[16];
    std::uint64_t load_fnv;
    std::uint64_t bytes_fnv;
};

inline constexpr InterleaverVector interleavers[] = {""")
for l in L:
    if l.startswith("il"):
        d = dict(re.findall(r"(\w+)=(\w+)", l))
        m = re.search(r"load16 \{(.*?)\} fnvLoad (0x\w+) fnvBytes (0x\w+)", l)
        assert d["rt"] == "True"
        o.append(f"    {{{d['wn']}, {d['kind']}, {{{m[1]}}}, {m[2]}ULL, {m[3]}ULL}},")
o.append("};\n\n}  // namespace csharp_vectors")
print("\n".join(o))
